'use client';
import { Nav, NavItem, NavLink } from 'react-bootstrap';
import Link from 'next/link';
import { usePathname } from 'next/navigation';

export default function TOC() {
  const pathname = usePathname();

  const isActive = (path: string) => {
    if (path === '/Labs') {
      return pathname === '/Labs';
    }
    return pathname.startsWith(path);
  };

  return (
    <Nav variant="pills" className="d-flex flex-row flex-wrap">
      <NavItem>
        <NavLink
          href="/Labs"
          as={Link}
          active={isActive('/Labs')}
        >
          Labs
        </NavLink>
      </NavItem>
      <NavItem>
        <NavLink
          href="/Labs/Lab1"
          as={Link}
          active={isActive('/Labs/Lab1')}
        >
          Lab 1
        </NavLink>
      </NavItem>
      <NavItem>
        <NavLink
          href="/Labs/Lab2"
          as={Link}
          active={isActive('/Labs/Lab2')}
        >
          Lab 2
        </NavLink>
      </NavItem>
      <NavItem>
        <NavLink
          href="/Labs/Lab3"
          as={Link}
          active={isActive('/Labs/Lab3')}
        >
          Lab 3
        </NavLink>
      </NavItem>
      <NavItem>
        <NavLink
          href="/"
          as={Link}
          active={pathname === '/'}
        >
          Kambaz
        </NavLink>
      </NavItem>
      <NavItem>
        <NavLink href="https://github.com/karynayen/kanbas-next-js">
          My GitHub
        </NavLink>
      </NavItem>
    </Nav>
  );
}
